UPDATE lesson_blocks SET data = '{"title":"From a point, the angle of elevation to a tree top is $35^\\circ$. Moving 10 m closer, it becomes $50^\\circ$. How tall is the tree?","steps":[{"latex":"h = x\\tan 50^\\circ = (x + 10)\\tan 35^\\circ","explanation":"x is the closer distance."},{"latex":"x(\\tan 50^\\circ - \\tan 35^\\circ) = 10\\tan 35^\\circ","explanation":""},{"latex":"x = \\tfrac{7.0021}{1.19175 - 0.70021} \\approx 14.25,\\ h \\approx 16.98 \\text{ m}","explanation":""}]}' WHERE id = 'blk_bfa7e3586072ff' AND data = '{"title":"From a point, the angle of elevation to a tree top is $35^\\circ$. Moving 10 m closer, it becomes $50^\\circ$. How tall is the tree?","steps":[{"latex":"h = x\\tan 50^\\circ = (x + 10)\\tan 35^\\circ","explanation":"x is the closer distance."},{"latex":"x(\\tan 50^\\circ - \\tan 35^\\circ) = 10\\tan 35^\\circ","explanation":""},{"latex":"x = \\tfrac{7.002}{1.1918 - 0.7002} \\approx 14.24,\\ h \\approx 16.97 \\text{ m}","explanation":""}]}';
