UPDATE lesson_blocks SET data = '{"body":"Common results: slicing a cylinder parallel to its base gives a circle, and perpendicular to the base (through the axis) gives a rectangle. A cone sliced parallel to the base gives a circle; through the apex perpendicular to the base gives a triangle; at a slight tilt that misses the base, an ellipse. Every plane section of a sphere is a circle. A cube can give a square, a rectangle, a triangle, or even a regular hexagon if sliced through the midpoints of six edges."}' WHERE id = 'blk_a26d2555fcbf76' AND data = '{"body":"Common results: slicing a cylinder parallel to its base gives a circle, and perpendicular to the base (through the axis) gives a rectangle. A cone sliced parallel to the base gives a circle; through the apex perpendicular to the base gives a triangle; at a tilt, an ellipse. Every plane section of a sphere is a circle. A cube can give a square, a rectangle, a triangle, or even a regular hexagon if sliced through the midpoints of six edges."}';
