UPDATE lesson_blocks SET data = '{"title":"A ring of radius R and charge Q, on its axis at distance x","steps":[{"latex":"dE_x = \\tfrac{k\\,dq}{x^2 + R^2}\\cdot\\tfrac{x}{\\sqrt{x^2 + R^2}}","explanation":"Perpendicular parts cancel around the ring."},{"latex":"E = \\tfrac{kQx}{(x^2 + R^2)^{3/2}}","explanation":"Zero at the center, and kQ/x² far away."},{"latex":"Q = 5\\ \\text{nC},\\ R = 0.3,\\ x = 0.4:\\ E \\approx 144\\ \\text{N/C}","explanation":""}]}' WHERE id = 'blk_1056bf20de73e0' AND data = '{"title":"A ring of radius R and charge Q, on its axis at distance x","steps":[{"latex":"dE_x = \\tfrac{k\\,dq}{x^2 + R^2}\\cdot\\tfrac{x}{\\sqrt{x^2 + R^2}}","explanation":"Perpendicular parts cancel around the ring."},{"latex":"E = \\tfrac{kQx}{(x^2 + R^2)^{3/2}}","explanation":"Zero at the center, and kQ/x² far away."},{"latex":"Q = 5\\ \\text{nC},\\ R = 0.3,\\ x = 0.4:\\ E \\approx 108\\ \\text{N/C}","explanation":""}]}';
