UPDATE lesson_blocks SET data = '{"term":"Gibbs free energy","body":"$\\Delta G = \\Delta H - T\\Delta S$ at constant temperature and pressure. $\\Delta G < 0$: thermodynamically favorable (proceeds without continuous outside energy). $\\Delta G > 0$: the reverse is favorable. $\\Delta G = 0$: equilibrium. The $\\Delta H$ term accounts for the entropy change of the surroundings ($\\Delta S_{surr} = -\\Delta H/T$)."}' WHERE id = 'blk_0545bda5aa3b79' AND data = '{"term":"Gibbs free energy","body":"$\\Delta G = \\Delta H - T\\Delta S$ at constant temperature and pressure. $\\Delta G < 0$: thermodynamically favorable (proceeds without continuous outside energy). $\\Delta G > 0$: the reverse is favorable. $\\Delta G = 0$: equilibrium. The $-T\\Delta S$ term accounts for the entropy change of the surroundings."}';
