UPDATE lesson_blocks SET data = '{"term":"Waves","body":"A wave carries energy without carrying matter along. In a transverse wave (a wave on a string) the medium moves perpendicular to the wave''s travel (light is also transverse, though it needs no medium); in a longitudinal wave (sound) it moves back and forth along it."}' WHERE id = 'blk_0495a70c5769b6' AND data = '{"term":"Waves","body":"A wave carries energy without carrying matter along. In a transverse wave (a string, light) the medium moves perpendicular to the wave''s travel; in a longitudinal wave (sound) it moves back and forth along it."}';
UPDATE lesson_blocks SET data = '{"tone":"application","title":"Where this shows up","body":"Cashiers group coins to make round numbers, and spreadsheets and computer algebra systems rearrange expressions using exactly these rules. Computer floating-point arithmetic rounds every result, so it is not perfectly associative, and it is why typing 0.1 + 0.2 can give 0.30000000000000004."}' WHERE id = 'blk_ab27255dfa58a4' AND data = '{"tone":"application","title":"Where this shows up","body":"Cashiers group coins to make round numbers, and spreadsheets and computer algebra systems rearrange expressions using exactly these rules. Computer floating-point arithmetic is famous for not being perfectly associative, which is why programmers sometimes get 0.30000000000000004."}';
UPDATE lesson_blocks SET data = '{"body":"Why does AA work? Dilate the smaller triangle so the side between the two angles matches the larger triangle''s corresponding side. Now the two triangles have two congruent angles and the included side congruent, so they''re congruent by ASA. Undo the dilation: the originals were similar."}' WHERE id = 'blk_5df42a8581ba8e' AND data = '{"body":"Why does AA work? Dilate the smaller triangle so one side matches the larger triangle''s corresponding side. Now the two triangles have two congruent angles and the included side congruent, so they''re congruent by ASA. Undo the dilation: the originals were similar."}';
UPDATE lesson_blocks SET data = '{"activity":"vertex-explorer","title":"Walkthrough: from y = x² to any parabola","steps":[{"title":"The parent graph","body":"y = x² has its vertex at the origin and opens up.","params":{"a":1,"h":0,"k":0}},{"title":"Shift right","body":"Replacing x with (x − 2) moves every point 2 units right: the vertex is now (2, 0).","params":{"a":1,"h":2,"k":0}},{"title":"Shift down","body":"Subtracting 3 moves the graph down: vertex (2, −3). It now crosses the x-axis twice.","params":{"a":1,"h":2,"k":-3}},{"title":"Flip and stretch","body":"a = −2 flips it upside down and makes it narrower, and k = 3 moves the vertex up to (2, 3). The vertex is now a maximum.","params":{"a":-2,"h":2,"k":3}}]}' WHERE id = 'blk_86f1a3845dac36' AND data = '{"activity":"vertex-explorer","title":"Walkthrough: from y = x² to any parabola","steps":[{"title":"The parent graph","body":"y = x² has its vertex at the origin and opens up.","params":{"a":1,"h":0,"k":0}},{"title":"Shift right","body":"Replacing x with (x − 2) moves every point 2 units right: the vertex is now (2, 0).","params":{"a":1,"h":2,"k":0}},{"title":"Shift down","body":"Subtracting 3 moves the graph down: vertex (2, −3). It now crosses the x-axis twice.","params":{"a":1,"h":2,"k":-3}},{"title":"Flip and stretch","body":"a = −2 flips it upside down and makes it narrower. The vertex is now a maximum.","params":{"a":-2,"h":2,"k":3}}]}';
UPDATE lesson_blocks SET data = '{"title":"$\\sum_{n=1}^{\\infty} \\dfrac{2^n}{n!}$","steps":[{"latex":"\\frac{2^{n+1}/(n + 1)!}{2^n/n!} = \\frac{2}{n + 1}","explanation":"Using $(n + 1)! = (n + 1)\\,n!$."},{"latex":"L = 0 < 1 \\Rightarrow \\text{converges}","explanation":"Its sum is $e^2 - 1$."}]}' WHERE id = 'blk_dc97e0db5140b9' AND data = '{"title":"$\\sum \\dfrac{2^n}{n!}$","steps":[{"latex":"\\frac{2^{n+1}/(n + 1)!}{2^n/n!} = \\frac{2}{n + 1}","explanation":"Using $(n + 1)! = (n + 1)\\,n!$."},{"latex":"L = 0 < 1 \\Rightarrow \\text{converges}","explanation":"Its sum is $e^2 - 1$."}]}';
UPDATE lesson_blocks SET data = '{"tone":"application","title":"Where this shows up","body":"Windshield-wiper delays, camera flashes and blinking LEDs can all be timed by RC circuits."}' WHERE id = 'blk_575610a39ed0ad' AND data = '{"tone":"application","title":"Where this shows up","body":"Windshield-wiper delays, camera flashes, pacemakers and the blinking of LEDs are all timed by RC circuits."}';
UPDATE lesson_blocks SET data = '{"tone":"application","title":"Where this shows up","body":"Many car side mirrors are convex (wider view, objects closer than they appear); headlights and telescopes use concave mirrors."}' WHERE id = 'blk_dc69a2105cbfcb' AND data = '{"tone":"application","title":"Where this shows up","body":"Car side mirrors are convex (wider view, objects closer than they appear); headlights and telescopes use concave mirrors."}';
UPDATE lesson_blocks SET data = '{"body":"A reflection is a rigid motion, so lengths and angles are preserved, but it reverses orientation: a clockwise labeling becomes counterclockwise. A figure has line symmetry if some reflection maps it onto itself. A square has 4 lines of symmetry, a (non-square) rectangle 2, an isosceles triangle that isn''t equilateral 1, and an equilateral triangle 3."}' WHERE id = 'blk_309629d5d4998a' AND data = '{"body":"A reflection is a rigid motion, so lengths and angles are preserved, but it reverses orientation: a clockwise labeling becomes counterclockwise. A figure has line symmetry if some reflection maps it onto itself. A square has 4 lines of symmetry, a rectangle 2, an isosceles triangle 1."}';
UPDATE lesson_blocks SET data = '{"term":"Reading the graphs","body":"Speed is greatest at equilibrium ($x = 0$) and zero at the turning points. Acceleration is greatest in magnitude at the turning points and zero at equilibrium. The velocity graph is a quarter-cycle ahead of the position graph."}' WHERE id = 'blk_0e72b4aff29b9d' AND data = '{"term":"Reading the graphs","body":"Speed is greatest at equilibrium ($x = 0$) and zero at the turning points. Acceleration is greatest in magnitude at the turning points and zero at equilibrium. The velocity graph is a quarter-cycle behind the position graph."}';
