UPDATE lesson_blocks SET data = '{"title":"A random sample of 12 used cars: price drop vs age, $b = 2.4$ (thousand dollars lost per year), $SE_b = 0.8$. Build a 95% interval.","steps":[{"latex":"df = 10,\\ t^* = 2.228","explanation":""},{"latex":"2.4 \\pm 2.228(0.8) = 2.4 \\pm 1.78","explanation":""},{"latex":"(0.62,\\ 4.18)","explanation":"We are 95% confident the true mean price drop is between about 620 and 4,180 dollars per year of age."}]}' WHERE id = 'blk_429d65e681e401' AND data = '{"title":"A random sample of 12 used cars: price vs age, $b = 2.4$ (thousand dollars lost per year), $SE_b = 0.8$. Build a 95% interval.","steps":[{"latex":"df = 10,\\ t^* = 2.228","explanation":""},{"latex":"2.4 \\pm 2.228(0.8) = 2.4 \\pm 1.78","explanation":""},{"latex":"(0.62,\\ 4.18)","explanation":"We are 95% confident the true mean price drop is between about 620 and 4,180 dollars per year of age."}]}';
UPDATE practice_questions SET hints = '["Find the signs of $v(2.5)$ and $a(2.5)$ separately.","Same signs mean speeding up; opposite signs mean slowing down."]' WHERE id = 'q_a0ede05626af23' AND hints = '["$v(2.5) < 0$, $a(2.5) = 3 > 0$."]';
UPDATE lesson_blocks SET data = '{"tone":"application","title":"Where this shows up","body":"Lab stock solutions, pool chemistry and industrial cleaning all rely on quick strong-acid and strong-base pH estimates; a 10-fold dilution of a strong acid raises its pH by 1, until it is so dilute that water''s own ions matter."}' WHERE id = 'blk_3eb22e2b988a41' AND data = '{"tone":"application","title":"Where this shows up","body":"Lab stock solutions, pool chemistry and industrial cleaning all rely on quick strong-acid and strong-base pH estimates; a 10-fold dilution of a strong acid raises its pH by exactly 1."}';
UPDATE lesson_blocks SET data = '{"tone":"application","title":"Where this shows up","body":"High jumpers arch over the bar so their center of mass can pass below it; trucks tip when their center of mass moves outside the base of support formed by their wheels."}' WHERE id = 'blk_19abf35b4dc42e' AND data = '{"tone":"application","title":"Where this shows up","body":"High jumpers arch over the bar so their center of mass can pass below it; trucks tip when their center of mass moves outside the wheelbase."}';
UPDATE lesson_blocks SET data = '{"term":"Conditions (near-normal incidence)","body":"If exactly one reflection is shifted (a soap film in air, oil on water): constructive when $2nt = (m + \\frac12)\\lambda$, destructive when $2nt = m\\lambda$. If both or neither are shifted (a coating on glass): swap the two conditions."}' WHERE id = 'blk_91739d04d1fcfd' AND data = '{"term":"Conditions (near-normal incidence)","body":"If exactly one reflection is shifted (a soap film in air): constructive when $2nt = (m + \\frac12)\\lambda$, destructive when $2nt = m\\lambda$. If both or neither are shifted (oil on water, coatings on glass): swap the two conditions."}';
UPDATE practice_questions SET prompt = 'Write the function for $|x|$ reflected over the x-axis, shifted right 3 and up 2. Use the format y=a|x-h|+k.' WHERE id = 'q_10c6f3612c730a' AND prompt = 'Write the function for $|x|$ reflected over the x-axis, shifted right 3 and up 2. Use the format y=-|x-3|+2.';
UPDATE lesson_blocks SET data = '{"term":"The other four","body":"With $(\\sin x)'' = \\cos x$ and $(\\cos x)'' = -\\sin x$, the remaining four are $(\\tan x)'' = \\sec^2 x$, $(\\cot x)'' = -\\csc^2 x$, $(\\sec x)'' = \\sec x \\tan x$, $(\\csc x)'' = -\\csc x \\cot x$. The \"co-\" functions get a minus sign."}' WHERE id = 'blk_7ae7eefe58e28b' AND data = '{"term":"All six","body":"$(\\tan x)'' = \\sec^2 x$, $(\\cot x)'' = -\\csc^2 x$, $(\\sec x)'' = \\sec x \\tan x$, $(\\csc x)'' = -\\csc x \\cot x$. The \"co-\" functions get a minus sign."}';
UPDATE practice_questions SET data = '{"choices":["70% of runners were faster than her","30% of runners had times at or below hers","She was 30% faster than average","She finished 30th"],"answer":1}' WHERE id = 'q_34e44a2f74e49c' AND data = '{"choices":["30% of runners were faster or tied","30% of runners had times at or below hers","She was 30% faster than average","She finished 30th"],"answer":1}';

-- Courses that now have published lessons are in development, not planned.
UPDATE courses SET status = 'in_development', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
   WHERE status = 'planned' AND id IN (
     SELECT u.course_id FROM chapter_lessons cl JOIN lessons l ON l.id = cl.lesson_id
     JOIN chapters ch ON ch.id = cl.chapter_id JOIN units u ON u.id = ch.unit_id WHERE l.status = 'published');
